def compute(vars):
    operating_lease_obligations = vars["v1"]
    capital_lease_obligations = vars["v2"]
    difference = operating_lease_obligations - capital_lease_obligations

    return {
        "value": difference,
        "trace": {
            "operating_lease_obligations": operating_lease_obligations,
            "capital_lease_obligations": capital_lease_obligations,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
